using WypozyczalniaSportowa.Domain.Exceptions;
namespace WypozyczalniaSportowa.Domain;

public sealed class Rental : Entity { private readonly List<RentalLine> _lines = []; private decimal? _total; public Rental(Customer customer, RentalPeriod period) { Customer = customer; Period = period; } internal Rental(int id, Customer customer, RentalPeriod period) : base(id) { Customer = customer; Period = period; } public Customer Customer { get; } public RentalPeriod Period { get; } public IReadOnlyList<RentalLine> Lines => _lines.AsReadOnly(); public RentalStatus Status { get; private set; } = RentalStatus.Active; public decimal Total => _total ?? _lines.Sum(x => x.ChargedPrice); public void AddLine(Equipment equipment, decimal price) { if (Status != RentalStatus.Active) throw new DomainValidationException("Zamkniętej rezerwacji nie można edytować."); if (_lines.Any(x => x.Equipment.Id == equipment.Id)) throw new DomainValidationException("Sprzęt jest już dodany."); _lines.Add(new RentalLine(equipment, price)); _total = null; } public void SetFinalTotal(decimal total) => _total = total < 0 ? throw new DomainValidationException("Kwota musi być nieujemna.") : total; public void MarkReturned() { if (Status == RentalStatus.Returned) throw new DomainValidationException("Rezerwacja jest już zwrócona."); Status = RentalStatus.Returned; } internal void RestoreStatus(RentalStatus s) => Status = s; public override Entity Clone(bool deep) { if (!deep) return (Rental)MemberwiseClone(); var copy = new Rental(Id, (Customer)Customer.Clone(true), Period); foreach (var line in _lines) copy._lines.Add(line.Clone(deep)); copy.Status = Status; copy._total = _total; return copy; } public override string ToString() => $"Rezerwacja #{Id}: {Customer.FullName}, {Period}, {Status}, {Total:C}"; }
